import { animate } from './vendor/anime.js';
import { createImmersion } from './immersion.js';
import { createAcademy } from './academy.js';
import { mountMotion, storyMarkup } from './motion.js';
let motionCleanup=()=>{};
const immersion=createImmersion();
const main=document.querySelector('main'), dialog=document.querySelector('dialog');
const data=await fetch('./data.json').then(r=>{if(!r.ok)throw Error('Не удалось загрузить каталог');return r.json()}).catch(e=>{main.innerHTML=`<div class="page"><h1>Каталог временно недоступен</h1><p>Перезагрузите страницу, чтобы попробовать снова.</p></div>`;throw e});
const byId=new Map(data.nodes.map(n=>[n.id,n])), cats=new Map(data.categories.map(c=>[c.id,c]));
let done=new Set(),projectDone=new Set(),track='eeg',category='all',query='',status='all',resourceFilter='all',graph,graphPromise,selected=null,mapCategory='all',listMode=false,pathMode=false,toastTimer;
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
let reduced=motionQuery.matches;
try{const savedMotion=localStorage.getItem('neuroatlas-motion');if(savedMotion!==null)reduced=savedMotion==='reduced'}catch{}
function updateRotateButton(active){const button=document.querySelector('#toggleRotate');if(!button)return;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',active?'Стоп — остановить вращение':'Вращать карту автоматически');button.title=active?'Остановить вращение':'Вращать карту автоматически';}
function applyMotion(){document.documentElement.dataset.motion=reduced?'reduced':'full';const b=document.querySelector('#motionPreference');b.setAttribute('aria-pressed',String(reduced));b.setAttribute('aria-label',reduced?'Включить движение':'Уменьшить движение');b.title=reduced?'Включить движение':'Уменьшить движение';graph?.setReduced(reduced);if(reduced)updateRotateButton(false);motionCleanup();motionCleanup=mountMotion(main,reduced)}
function setMotion(value){reduced=value;try{localStorage.setItem('neuroatlas-motion',value?'reduced':'full')}catch{}applyMotion();}
motionQuery.addEventListener?.('change',e=>{let hasPreference=false;try{hasPreference=localStorage.getItem('neuroatlas-motion')!==null}catch{}if(!hasPreference){reduced=e.matches;applyMotion()}});
try{const s=JSON.parse(localStorage.getItem('neuroatlas-progress')||'{}');done=new Set((s.done||[]).filter(id=>byId.has(id)));projectDone=new Set((s.projects||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<data.projects.length));track=data.tracks.some(t=>t.id===s.track)?s.track:'eeg';}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catColor=id=>cats.get(id)?.color||'#abc58a';
const nodeChip=id=>{const n=byId.get(id);return n?`<button class="node-chip ${done.has(id)?'done':''}" data-topic="${id}">${id} · ${esc(n.title)}${done.has(id)?' ✓':''}</button>`:''};
function ancestors(id,visited=new Set()){for(const p of byId.get(id)?.deps||[]){if(!visited.has(p)){visited.add(p);ancestors(p,visited)}}return visited;}
const dependents=id=>data.nodes.filter(n=>n.deps.includes(id));
function save(){try{localStorage.setItem('neuroatlas-progress',JSON.stringify({version:1,done:[...done],projects:[...projectDone],track}));}catch{toast('Браузер не сохранил прогресс. Он доступен до закрытия страницы.')}updateProgress()}
function updateProgress(){document.getElementById('progressText').textContent=`${done.size} / ${data.nodes.length}`;}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;clearTimeout(toastTimer);animate(el,{opacity:[0,1],y:[6,0],duration:reduced?0:220});toastTimer=setTimeout(()=>animate(el,{opacity:0,duration:reduced?0:200}),3000)}
function toggleDone(id){done.has(id)?done.delete(id):done.add(id);save();document.querySelectorAll(`[data-complete="${id}"]`).forEach(b=>{b.classList.toggle('done',done.has(id));b.setAttribute('aria-pressed',String(done.has(id)));b.textContent=b.classList.contains('module-check')?(done.has(id)?'✓':'+'):(done.has(id)?'✓ Изучено':'Отметить изученным')});toast(done.has(id)?'Модуль отмечен изученным':'Отметка снята');if(graph)graph.setProgress(done);if(currentPage==='curriculum')renderCatalog();if(dialog.open&&dialog.dataset.topic===id)fillDialog(id);if(selected===id&&currentPage==='map')renderMapPanel();}
let currentPage='overview';
const academy=createAcademy(data,{done:()=>done,track:()=>track,progress:()=>({version:1,done:[...done],projects:[...projectDone],track}),toast,render,mergeProgress(ids,projects){ids.forEach(id=>done.add(id));projects.forEach(id=>projectDone.add(id));save();graph?.setProgress(done);}});
const title=(eyebrow,h,p)=>`<h1 class="page-title">${h}</h1><p class="lead">${p}</p>`;
const section=(h,p='',right='')=>`<div class="section-top"><div><h2>${h}</h2>${p?`<p>${p}</p>`:''}</div>${right}</div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const moduleRow=n=>`<div class="module-row"><button class="module-code" data-topic="${n.id}" aria-label="Карточка темы ${esc(n.title)}">${n.id}</button><a class="module-open" href="#lesson?id=${n.id}"><h3>${esc(n.title)}</h3><p>${esc(n.topics.slice(0,3).join(' · '))}</p><div class="module-meta"><span>${n.deps.length?`${n.deps.length} предварительных тем`:'Можно начинать'}</span><span>${done.has(n.id)?'ИЗУЧЕНО':n.deps.every(d=>done.has(d))?'ГОТОВО К ИЗУЧЕНИЮ':'ПОСМОТРЕТЬ ЗАВИСИМОСТИ'}</span></div></a><button class="module-check ${done.has(n.id)?'done':''}" data-complete="${n.id}" aria-label="${done.has(n.id)?'Снять отметку':'Отметить изученным'}: ${esc(n.title)}" aria-pressed="${done.has(n.id)}">${done.has(n.id)?'✓':'+'}</button></div>`;
function overview(){return `<div class="page"><div class="hero"><div><h1>От нейрона<br>к <em>интерфейсу.</em></h1><p>Разберитесь, как связаны науки о мозге.<br>Постройте свой путь от первых знаний<br>до работающего нейроинтерфейса.</p><div class="hero-actions"><a class="button primary" href="#map">Исследовать карту <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a><a class="button ghost" href="#routes">Выбрать маршрут <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-right"></use></svg></a></div><div class="hero-note"><span>116 МОДУЛЕЙ</span><span>293 СВЯЗИ</span><span>5 МАРШРУТОВ</span></div></div><div class="hero-stage" id="graphMount"><div class="stage-tag"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#orbit"></use></svg><span>Исследуйте пространство знаний</span></div><div class="map-loading"><span class="loading-orbit" aria-hidden="true"></span><span>Собираем пространство знаний…</span></div><div class="stage-bottom"><span>Каждая точка — начало новой связи.</span><a href="#map" aria-label="Открыть трехмерную карту"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a></div></div></div><div class="stats-strip"><div class="stat"><strong>10</strong><span>направлений<br>общего фундамента</span></div><div class="stat"><strong>116</strong><span>лекций<br>с примерами и практикой</span></div><div class="stat"><strong>13</strong><span>практических<br>проектов</span></div><div class="stat"><strong>18</strong><span>ресурсов<br>для самостоятельной работы</span></div></div>${academy.continueCard()}${storyMarkup()}${section('Знания образуют систему.','Выберите направление — увидите темы, их связи и проверяемые результаты.','<a class="text-link" href="#curriculum">Вся программа <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a>')}<div class="field-grid">${data.categories.map((c,i)=>`<a class="field-card" href="#curriculum?category=${c.id}"><span class="code">${String(i+1).padStart(2,'0')} <span class="color-dot" style="--color:${c.color}"></span></span><h3>${c.name}</h3><p>${data.nodes.filter(n=>n.category===c.id).length} модулей <span style="float:right">↗</span></p></a>`).join('')}</div><div class="journey-band"><div><h2>Не нужно изучить всё,<br>чтобы сделать первый шаг.</h2><p>Для первого EEG-прототипа достаточно выбранной части фундамента. Исследовательскую глубину добавляйте под свою задачу.</p><a class="button primary" href="#routes">Найти свой путь <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-right"></use></svg></a></div><div class="mini-steps"><div class="mini-step"><b>01</b><span>Понять происхождение сигнала</span></div><div class="mini-step"><b>02</b><span>Построить и проверить декодер</span></div><div class="mini-step"><b>03</b><span>Добавить управление и обратную связь</span></div><div class="mini-step"><b>04</b><span>Выбрать исследовательскую специализацию</span></div></div></div>${section('Что объединяет нейрокибернетика','Два параллельных пути: объяснять нервную систему и создавать интерфейсы, взаимодействующие с ней.')}<div class="reading-grid"><div class="reading-card"><h3>Практический BCI</h3><p>Измерить сигнал → обработать → декодировать → передать команду → проверить работу с пользователем. В центре — работающая система и ее полезность.</p></div><div class="reading-card"><h3>Вычислительная нейронаука</h3><p>Построить модель → проверить на данных → понять механизм → использовать понимание в интерфейсе. Подробная биофизическая модель не обязательна для первого EEG-декодера.</p></div></div><details><summary class="text-link" style="margin-top:22px;cursor:pointer">Все науки и их роль в BCI ↓</summary>${table(['Область','Главный вопрос','Значение для BCI'],data.areas)}</details>${section('От записи — к взаимодействию','Модальность определяет физику сигнала, ограничения и последующую специализацию.')}<details><summary class="text-link" style="cursor:pointer">Сравнить 11 типов регистрации и интерфейсов ↓</summary>${table(['Модальность','Что измеряется','Что добавить','Задачи','Ограничения'],data.modalities)}</details><div class="note"><b>Учебная карта, а не жесткое расписание.</b> Стрелки обозначают рекомендуемые зависимости. Направления можно изучать параллельно; отметка «изучено» отражает вашу самооценку, а не сертификат.</div>${section('Шесть ступеней самостоятельности','Оценивайте себя по тому, что можете объяснить, реализовать и проверить.')}<div class="milestones">${data.milestones.map(([h,p],i)=>`<div class="milestone"><b>0${i+1}</b><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div>`}
function curriculum(){return `<div class="page">${title('01 / Учебная программа','Фундамент. Связи. Практика.','116 лекций: от Python и электрофизиологии до речевых нейропротезов. В каждой — объяснения, разобранный пример, упражнение и самопроверка.')}<div class="catalog-action"><a class="button" href="#schedule">Моё расписание</a><span>Название открывает лекцию · код модуля — зависимости</span></div><div class="toolbar"><label class="search"><input id="catalogSearch" type="search" placeholder="Найти тему: EEG, вероятность, речь…" aria-label="Поиск учебных модулей" value="${esc(query)}"></label><select id="catalogStatus" aria-label="Статус изучения"><option value="all">Все темы</option><option value="ready">Готовы к изучению</option><option value="done">Изученные</option><option value="todo">Еще не изученные</option></select></div><div class="chips" id="catalogChips">${categoryChips(category,'catalog-category')}</div><div class="catalog-layout"><aside class="catalog-side"><h3>${done.size} из ${data.nodes.length} модулей</h3><div class="progress-bar"><i style="width:${done.size/data.nodes.length*100}%"></i></div><p>Отмечайте знания, которыми уже владеете. Двигайтесь по зависимостям или выбранному маршруту.</p><a class="button small" href="#routes">Мой маршрут <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-right"></use></svg></a><p class="storage-note">Прогресс сохраняется в этом браузере. Между устройствами он не синхронизируется.</p></aside><div id="catalogResults"></div></div>${section('Три уровня глубины')}<div class="reading-grid"><div class="reading-card"><h3>Обзор</h3><p>Объяснить идею, назначение и ограничения.</p></div><div class="reading-card"><h3>Рабочий уровень</h3><p>Самостоятельно применить метод, проверить результат и разобрать ошибки.</p></div><div class="reading-card"><h3>Исследовательский уровень</h3><p>Читать статьи, воспроизводить методы и обосновывать изменения.</p></div><div class="reading-card"><h3>Как выбирать глубину</h3><p>Для первого BCI большинству базовых модулей достаточно рабочего уровня. Исследовательская глубина нужна в выбранной специализации.</p></div></div></div>`}
function categoryChips(active,attr){return `<button class="chip ${active==='all'?'active':''}" data-${attr}="all">Все направления</button>`+data.categories.map(c=>`<button class="chip ${active===c.id?'active':''}" data-${attr}="${c.id}"><span class="color-dot" style="--color:${c.color}"></span>${c.name}</button>`).join('')}
function renderCatalog(){const el=document.querySelector('#catalogResults');if(!el)return;let nodes=data.nodes.filter(n=>(category==='all'||n.category===category)&&(!query||`${n.id} ${n.title} ${n.topics.join(' ')} ${n.outcome}`.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')))&&(status==='all'||status==='done'&&done.has(n.id)||status==='todo'&&!done.has(n.id)||status==='ready'&&!done.has(n.id)&&n.deps.every(d=>done.has(d))));el.innerHTML=`<div class="view-counter">${nodes.length} МОДУЛЕЙ В ВЫБОРКЕ</div>`+(nodes.length?data.categories.map(c=>{const group=nodes.filter(n=>n.category===c.id);return group.length?`<section class="catalog-group"><div class="group-heading"><h2><span class="color-dot" style="--color:${c.color}"></span>${c.name}</h2><span>${c.en}</span></div>${group.map(moduleRow).join('')}</section>`:''}).join(''):`<div class="empty">Ничего не найдено. Измените запрос или фильтр.</div>`);document.querySelector('#catalogChips').innerHTML=categoryChips(category,'catalog-category');const side=document.querySelector('.catalog-side');if(side){side.querySelector('h3').textContent=`${done.size} из ${data.nodes.length} модулей`;side.querySelector('i').style.transform=`scaleX(${done.size/data.nodes.length})`}}
function routes(){return `<div class="page">${title('03 / Маршруты обучения','Ваш путь к нейроинтерфейсу.','Выберите цель. Этапы показывают основные темы, а 3D-карта раскрывает весь предварительный фундамент. Порядок — ориентир: переходите дальше по проверяемым результатам.')}<div class="route-grid">${data.tracks.map(t=>`<article class="route-card ${track===t.id?'selected':''}"><span class="route-letter">МАРШРУТ ${t.letter}</span><h2>${t.title}</h2><p>${t.description}</p><div class="buttons"><button class="button ${track===t.id?'primary':''} small" data-track="${t.id}">${track===t.id?'Выбран ✓':'Выбрать маршрут'}</button><a class="button ghost small" href="#map?id=${t.target}&path=1">На карте <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a></div></article>`).join('')}</div><div class="route-schedule-link"><a class="button primary" href="#schedule">Построить расписание этого маршрута</a><p>Зависимости, ваша нагрузка и уже изученные темы учитываются автоматически.</p></div><div id="routeDetail"></div><div class="note"><b>Рекомендованный вход для AI/ML:</b> Python → вероятность и линейная алгебра → нейрофизиология и сигналы → MNE → motor imagery baseline → перенос → вычислительная нейронаука → deep learning → потоковый BCI → ECoG или спайковые данные.</div></div>`}
function renderRouteDetail(){const t=data.tracks.find(t=>t.id===track),el=document.querySelector('#routeDetail');if(!el)return;const ids=new Set(t.steps.flat());ids.forEach(id=>ancestors(id).forEach(p=>ids.add(p)));const count=[...ids].filter(id=>done.has(id)).length;el.innerHTML=`<section class="route-detail"><h2 class="route-name">${t.title}</h2><h3 class="route-count">${count} / ${ids.size} тем с учетом зависимостей</h3><div class="progress-bar"><i style="width:${count/ids.size*100}%"></i></div>${t.steps.map((s,i)=>`<div class="route-step"><b>0${i+1}</b><div><h3>${['База и язык дисциплины','Методы и первые модели','Проверка, перенос и углубление','Самостоятельный прототип и исследование'][i]}</h3><div class="node-chips">${s.map(nodeChip).join('')}</div></div></div>`).join('')}<p class="storage-note">Этапы показывают ключевые модули. Откройте карточку темы или карту, чтобы увидеть все ее предварительные зависимости.</p><div class="note">${t.defer}</div><a class="button primary" href="#map?id=${t.target}&path=1">Посмотреть полный путь на карте <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a></section>`;}
function practice(){return `<div class="page">${title('04 / Практическая лаборатория','Знания становятся навыком.','13 проектов по возрастанию сложности. Завершайте каждый отчетом: данные, baseline, разбиение, неопределенность, ошибки и границы применимости.')}<div class="project-list">${data.projects.map((p,i)=>`<article class="project-card"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h2>${p.title}</h2><p>${p.description}</p><details><summary>Подготовка и критерий готовности</summary><div class="node-chips" style="margin-top:12px">${p.deps.map(nodeChip).join('')}</div><p class="outcome">${p.outcome}</p></details></div><button class="button small project-done ${projectDone.has(i)?'primary':''}" data-project="${i}" aria-pressed="${projectDone.has(i)}">${projectDone.has(i)?'✓ Завершен':'Отметить готовым'}</button></article>`).join('')}</div>${section('Проверять не только accuracy','Выбирайте метрику под задачу, а не под удобство получения красивого числа.')} ${table(['Задача','Основные метрики','Что добавлять'],data.metrics)}<div class="note"><b>ITR не универсален.</b> Интерпретация зависит от числа вариантов, времени выбора, распределения ошибок и структуры задачи. Пользовательская скорость с исправлениями часто важнее лабораторного показателя.</div>${section('Семь правил честного декодера')}<ol class="check-list">${data.checklist.map(t=>`<li>${t}</li>`).join('')}</ol>${section('Ошибки, которые меняют вывод')}<div class="reading-grid">${data.pitfalls.map(([t,d])=>`<div class="reading-card"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="note"><b>Переход к человеку и физическим устройствам.</b> Запись требует понятного протокола и согласия пользователя; визуальная стимуляция — учета переносимости мерцания и фоточувствительности. Имплантация и исследования стимуляции выполняются с профильной лабораторией и клинической командой. Начинайте такие ветки с открытых данных и симуляций.</div></div>`}
function resources(){return `<div class="page">${title('05 / Библиотека','Открытый доступ к знаниям.','Курсы, учебники, инструменты и данные из программы. Материалы доступны на сайтах авторов; требования доступа к отдельным данным и программам могут различаться.')}<div class="chips">${['all','Курс','Учебник','Инструмент','Данные','Документация','Практикум','Стандарт','Лекция','Руководство','Статья'].map(type=>`<button class="chip ${resourceFilter===type?'active':''}" data-resource="${type}">${type==='all'?'Все материалы':type}</button>`).join('')}</div><div class="resource-grid">${data.resources.filter(r=>resourceFilter==='all'||r.type===resourceFilter).map(r=>`<a class="resource-card" href="${r.url}" target="_blank" rel="noopener noreferrer"><small><span class="color-dot" style="--color:${catColor(r.category)}"></span>${r.type}</small><h2>${r.title}</h2><p>${r.description}</p><span>Открыть материал ↗</span></a>`).join('')}</div><div class="note"><b>Как учиться:</b> математическая база → Neuromatch и Neuronal Dynamics → MNE → MOABB → Braindecode. Для спайков добавьте SpikeInterface, для времени — LSL, для нейроданных — NWB и DANDI.</div><p class="storage-note">Карта зависимостей и критерии — авторская учебная конструкция. Ссылки ведут к официальным образовательным ресурсам, документации и публикациям. Каталог составлен 13 октября 2026 года.</p></div>`}
function mapPage(){return `<div class="map-page"><div class="map-stage" id="graphMount"><div class="map-loading"><span class="loading-orbit" aria-hidden="true"></span><span>Собираем пространство знаний…</span></div></div><div class="map-top"><div><h1>Карта зависимостей</h1><p>Вселенная знаний. Световой поток показывает следующий шаг.</p></div><div><label class="search"><input id="mapSearch" type="search" placeholder="Найти область или модуль…" aria-label="Поиск на карте" autocomplete="off"></label></div></div><div class="map-status">${data.nodes.length} NODES / ${data.nodes.reduce((s,n)=>s+n.deps.length,0)} CONNECTIONS / 3D</div><div id="mapResults" class="map-search-results"></div><button class="map-filter-toggle" id="filterToggle" aria-expanded="false">Направления <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#sliders-horizontal"></use></svg></button><aside class="map-filter" id="mapFilter"><div class="filter-label">НАПРАВЛЕНИЯ</div><button data-mapcat="all" class="${mapCategory==='all'?'active':''}">Все области <small>116</small></button>${data.categories.map(c=>`<button data-mapcat="${c.id}" class="${mapCategory===c.id?'active':''}"><span class="color-dot" style="--color:${c.color}"></span>${c.name}<small>${data.nodes.filter(n=>n.category===c.id).length}</small></button>`).join('')}</aside><aside class="map-panel" id="mapPanel" aria-live="polite"></aside><div class="map-legend"><span><i class="line-key"></i> Поток: основа → зависимая тема</span><span>● Цвет = направление · ✓ = изучено</span></div><div class="map-hint"><span><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#move"></use></svg> Потяните для вращения</span><span><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#mouse-pointer-2"></use></svg> Колесо / жест — приближение</span><span><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#orbit"></use></svg> Нажмите на узел</span></div><button class="immersion-exit" id="exitImmersion" aria-label="Выйти из режима погружения" title="Выйти (Escape)" hidden><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#x"></use></svg><span>Выйти</span></button><div class="map-controls" role="group" aria-label="Управление картой"><div class="map-zoom" role="group" aria-label="Масштаб карты"><button type="button" id="zoomOut" aria-label="Отдалить карту" title="Отдалить (−)"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#minus"></use></svg></button><span class="zoom-caption">Масштаб</span><button type="button" id="zoomIn" aria-label="Приблизить карту" title="Приблизить (+)"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#plus"></use></svg></button></div><button type="button" class="map-control" id="resetCamera" aria-label="Вся карта — вернуть общий вид" title="Вся карта — вернуть общий вид"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#scan"></use></svg><span class="control-copy"><span>Вся карта</span></span></button><button type="button" class="map-control" id="enterImmersion" aria-label="На весь экран — скрыть интерфейс" title="На весь экран — скрыть интерфейс"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#maximize"></use></svg><span class="control-copy"><span>На весь экран</span></span></button><button type="button" class="map-control" id="toggleRotate" aria-label="Вращать карту автоматически" title="Вращать карту автоматически" aria-pressed="false"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#rotate-cw"></use></svg><span class="control-copy"><span class="when-off">Вращать</span><span class="when-on">Стоп</span></span></button><button type="button" class="map-control" id="panelToggle" aria-label="Скрыть карточку" title="Скрыть карточку" aria-pressed="false"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#chevron-down"></use></svg><span class="control-copy"><span class="when-off">Скрыть карточку</span><span class="when-on">Показать карточку</span></span></button><button type="button" class="map-control" id="toggleList" aria-label="Список тем" title="Список тем" aria-pressed="false"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#list"></use></svg><span class="control-copy"><span class="when-off">Список тем</span><span class="when-on">Карта 3D</span></span></button><button type="button" class="map-control" id="mapHelp" aria-label="Как управлять" title="Как управлять"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#circle-help"></use></svg><span class="control-copy"><span>Как управлять</span></span></button></div><div class="map-alt-list" id="mapList" hidden></div></div>`}
function renderMapPanel(){const el=document.querySelector('#mapPanel');if(!el)return;if(!selected){el.innerHTML=`<h2>Связи важнее<br>отдельных фактов.</h2><p>Выберите сферу, чтобы приблизиться и увидеть темы, предварительные знания и следующие шаги. Приблизьте камеру: светящиеся точки превратятся в объемные сферы.</p><button class="button lime small" data-select="X12">Начать с EEG-прототипа <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></button><button class="button ghost small" id="showIntroHelp">Как исследовать карту</button>`;return}const n=byId.get(selected),parents=ancestors(n.id),next=dependents(n.id);el.innerHTML=`<button class="icon-btn" id="clearSelection" aria-label="Снять выбор"><svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#x"></use></svg></button><div class="topic-number">${n.id} / ${cats.get(n.category).en}</div><h2>${n.title}</h2><p>${n.topics.slice(0,4).join(' · ')}</p><h3>ПРЕДВАРИТЕЛЬНЫЕ ТЕМЫ · ${n.deps.length}</h3><div class="node-chips">${n.deps.length?n.deps.map(id=>`<button class="node-chip" data-select="${id}">${id} · ${byId.get(id).title}</button>`).join(''):'<span style="font-size:11px;color:#b5c5aa">Можно начинать здесь</span>'}</div><h3>ОТКРЫВАЕТ СЛЕДУЮЩИХ ТЕМ · ${next.length}</h3><div class="node-chips">${next.slice(0,4).map(n=>`<button class="node-chip" data-select="${n.id}">${n.id} · ${n.title}</button>`).join('')}${next.length>4?`<span style="font-size:11px">Еще ${next.length-4} — в карточке</span>`:''}</div><a class="button lime small" href="#lesson?id=${n.id}">Читать лекцию <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a><button class="button small ghost ${pathMode?'active':''}" id="togglePath">${pathMode?'✓ Весь путь подсвечен':`Подсветить весь путь (${parents.size})`}</button><button class="button small ghost" data-complete="${n.id}" aria-pressed="${done.has(n.id)}">${done.has(n.id)?'✓ Изучено':'Отметить изученным'}</button>`}
function selectNode(id,focus=true){if(!byId.has(id))return;selected=id;document.querySelector('.map-page')?.classList.remove('panel-hidden');document.querySelector('#panelToggle')?.setAttribute('aria-pressed','false');document.querySelector('#panelToggle')?.setAttribute('aria-label','Скрыть карточку');if(document.querySelector('#panelToggle'))document.querySelector('#panelToggle').title='Скрыть карточку темы';renderMapPanel();if(!reduced)animate(document.querySelector('#mapPanel'),{opacity:[.7,1],x:[8,0],duration:210,ease:'outExpo'});graph?.select(id,pathMode);if(focus)graph?.focus(id);document.querySelector('#mapResults')?.replaceChildren();document.querySelector('#mapFilter')?.classList.remove('open');document.querySelector('#filterToggle')?.setAttribute('aria-expanded','false');if(currentPage==='map')history.replaceState(null,'',`#map?id=${id}${pathMode?'&path=1':''}`)}
function renderMapList(){const el=document.querySelector('#mapList');if(!el)return;const q=document.querySelector('#mapSearch')?.value.toLowerCase()||'';const nodes=data.nodes.filter(n=>(mapCategory==='all'||n.category===mapCategory)&&`${n.id} ${n.title} ${n.topics.join(' ')}`.toLowerCase().includes(q));el.innerHTML=`<h2>Текстовая карта · ${nodes.length} тем</h2><p>Доступный способ исследовать те же узлы с клавиатуры. Каждая карточка содержит направленные зависимости.</p>${nodes.map(moduleRow).join('')||'<p>Ничего не найдено.</p>'}`;el.hidden=!listMode;if(listMode&&!reduced)animate(el,{opacity:[.6,1],duration:180});document.querySelector('#toggleList').classList.toggle('active',listMode);document.querySelector('#toggleList').setAttribute('aria-pressed',String(listMode));document.querySelector('#toggleList').setAttribute('aria-label',listMode?'Карта 3D':'Список тем');document.querySelector('#toggleList').title=listMode?'Вернуться к карте 3D':'Открыть список тем';}
function fillDialog(id){const n=byId.get(id),c=cats.get(n.category),next=dependents(id),res=data.resources.filter(r=>r.category===n.category||['M','P'].includes(n.category)&&r.category==='C').slice(0,4);dialog.dataset.topic=id;document.querySelector('#dialogContent').innerHTML=`<div class="topic-number">${n.id} / ${c.en}</div><h2 id="dialogTitle">${n.title}</h2><p>${c.brief}</p><a class="button primary" data-close-dialog href="#lesson?id=${id}">Читать лекцию и решить задания</a><h3>Что изучить</h3><ul>${n.topics.map(t=>`<li>${t}</li>`).join('')}</ul><h3>Проверяемый результат</h3><div class="outcome">${n.outcome}</div><h3>Предварительные знания · ${n.deps.length}</h3><div class="node-chips">${n.deps.length?n.deps.map(nodeChip).join(''):'<p>Базовая точка входа. Формальных зависимостей в карте нет.</p>'}</div><h3>Открывает следующие темы · ${next.length}</h3><div class="node-chips">${next.length?next.map(n=>nodeChip(n.id)).join(''):'<p>Конечная специализация. Дальше — проект и выбранный исследовательский вопрос.</p>'}</div>${res.length?`<h3>Материалы направления</h3><div class="dialog-resources">${res.map(r=>`<a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.title} <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a>`).join('')}</div>`:''}<div class="dialog-actions"><button class="button primary" data-complete="${id}" aria-pressed="${done.has(id)}">${done.has(id)?'✓ Изучено':'Отметить изученным'}</button><a class="button" data-close-dialog href="#map?id=${id}&path=1">Все зависимости на карте <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-up-right"></use></svg></a></div><p class="storage-note">Критерий — ориентир для самооценки. Материалы подобраны по направлению, а не как обязательный отдельный курс для каждого модуля.</p>`;}
function openTopic(id){if(!byId.has(id))return;fillDialog(id);if(!dialog.open){dialog.showModal();if(!reduced)animate(dialog,{opacity:[.7,1],scale:[.98,1],duration:240,ease:'outExpo'})}else if(!reduced)animate(document.querySelector('#dialogContent'),{opacity:[.65,1],duration:160});dialog.scrollTop=0;}
function showHelp(){delete dialog.dataset.topic;document.querySelector('#dialogContent').innerHTML=`<h2 id="dialogTitle">Исследуйте связи.</h2><div class="help-grid"><div><b>Вращение</b><p>Потяните карту мышью или одним пальцем.</p></div><div><b>Приближение</b><p>Колесо мыши, два пальца или кнопки + / −.</p></div><div><b>Перемещение</b><p>Правая кнопка мыши или два пальца. Кнопка ⌂ возвращает всю карту.</p></div><div><b>Выбор темы</b><p>Нажмите на узел или найдите его через поиск. Нажатие на узел или результат поиска плавно приближает камеру.</p></div><div><b>Световые потоки</b><p>Яркая голова импульса ведёт за собой шлейф частиц: от предварительной темы к той, которая от неё зависит. Выберите тему, чтобы выделить её связи, или включите весь путь.</p></div><div><b>Полное погружение</b><p>Кнопка «На весь экран» скрывает весь интерфейс и раскрывает карту на весь экран. Для выхода нажмите «Выйти» в углу или Escape. Вращение, приближение и выбор сфер продолжают работать.</p></div><div><b>Клавиатура и доступность</b><p>Tab — элементы управления. + / − — масштаб, Home — вся карта, Escape — снять выбор. «Список» показывает все узлы без 3D.</p></div></div><div class="note">Цвет обозначает направление. Подсветка всего пути показывает все предварительные зависимости. Точки плавно переходят в сферы по мере приближения. Звёзды и объекты окружают карту на 360°: туманности, галактики, чёрные дыры, пульсары, квазары, кометы, планеты с кольцами и шаровые скопления. Отключение анимаций останавливает космос и потоки.</div><button class="button" id="motionToggle">${reduced?'Включить':'Отключить'} анимации</button>`;if(!dialog.open)dialog.showModal();}
async function attachGraph(mode){const mount=document.querySelector('#graphMount');if(!mount)return;try{if(!graphPromise)graphPromise=import('./graph.js').then(m=>m.createGraph(data,{onSelect:id=>{if(currentPage==='overview')location.hash=`map?id=${id}`;else selectNode(id,true)},reduced}));graph=await graphPromise;if(!mount.isConnected)return;graph.mount(mount,mode);graph.setProgress(done);if(mode==='map'){graph.filter(mapCategory);graph.select(selected,pathMode);if(selected)graph.focus(selected)}else{graph.filter('all');graph.select(null,false)}mount.querySelector('.map-loading')?.remove();if(!reduced)animate(mount.querySelector('canvas'),{opacity:[.4,1],duration:500,ease:'outExpo'});}catch(e){if(!mount.isConnected)return;mount.querySelector('.map-loading')?.remove();const box=document.createElement('div');box.className='fallback';box.innerHTML=`<h2>3D недоступен в этом браузере</h2><p>Все темы и связи доступны в текстовом списке и программе.</p><a class="button lime" href="#curriculum">Открыть программу <svg class="ui-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="./vendor/icons.svg#arrow-right"></use></svg></a>`;mount.append(box);if(mode==='map'){listMode=true;renderMapList();}console.warn(e);}}
function render(){academy.flush();motionCleanup();immersion.exit(false);const [page,paramString]=(location.hash.slice(1)||'overview').split('?');currentPage=['overview','curriculum','map','routes','practice','resources','lesson','schedule'].includes(page)?page:'overview';const params=new URLSearchParams(paramString);if(currentPage==='curriculum'&&cats.has(params.get('category')))category=params.get('category');if(currentPage==='map'){selected=byId.has(params.get('id'))?params.get('id'):null;pathMode=params.get('path')==='1';listMode=false;}if(dialog.open)dialog.close();graph?.suspend();main.innerHTML=['lesson','schedule'].includes(currentPage)?academy.render(currentPage,params):({overview,curriculum,map:mapPage,routes,practice,resources}[currentPage])();document.querySelectorAll('nav a').forEach(a=>{const active=a.hash.slice(1)===(currentPage==='lesson'?'curriculum':currentPage);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.getElementById('footer').hidden=currentPage==='map';document.title=`${{overview:'От нейрона к интерфейсу',curriculum:'Учебная программа',map:'Карта зависимостей 3D',routes:'Маршруты',practice:'Практика',resources:'Ресурсы',lesson:byId.get(params.get('id'))?.title||'Лекция',schedule:'Моё расписание'}[currentPage]} — NEUROATLAS`;window.scrollTo({top:0,behavior:'instant'});if(currentPage==='curriculum'){document.querySelector('#catalogStatus').value=status;renderCatalog()}if(currentPage==='routes')renderRouteDetail();if(currentPage==='map'){renderMapPanel();renderMapList()}if(['overview','map'].includes(currentPage))attachGraph(currentPage);document.body.dataset.page=currentPage;decorateProgress();motionCleanup=mountMotion(main,reduced);academy.mount(currentPage);}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.topic)openTopic(el.dataset.topic);if(el.dataset.complete)toggleDone(el.dataset.complete);if(el.dataset.select)selectNode(el.dataset.select);if(el.dataset.catalogCategory){category=el.dataset.catalogCategory;renderCatalog()}if(el.dataset.track){track=el.dataset.track;academy.setTrack(track);save();motionCleanup();main.innerHTML=routes();renderRouteDetail();decorateProgress();motionCleanup=mountMotion(main,reduced);document.querySelector('#routeDetail').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})}if(el.dataset.project!==undefined){const i=Number(el.dataset.project);projectDone.has(i)?projectDone.delete(i):projectDone.add(i);save();el.textContent=projectDone.has(i)?'✓ Завершен':'Отметить готовым';el.classList.toggle('primary',projectDone.has(i));el.setAttribute('aria-pressed',String(projectDone.has(i)))}if(el.dataset.resource){resourceFilter=el.dataset.resource;motionCleanup();main.innerHTML=resources();motionCleanup=mountMotion(main,reduced);if(!reduced)animate(document.querySelector('.resource-grid'),{opacity:[.75,1],duration:160})}if(el.dataset.mapcat){mapCategory=el.dataset.mapcat;graph?.filter(mapCategory);document.querySelectorAll('[data-mapcat]').forEach(b=>b.classList.toggle('active',b.dataset.mapcat===mapCategory));renderMapList()}if(el.hasAttribute('data-close-dialog'))dialog.close();switch(el.id){case'enterImmersion':immersion.enter();break;case'exitImmersion':immersion.exit();break;case'progressButton':status='done';category='all';query='';if(currentPage==='curriculum'){document.querySelector('#catalogSearch').value='';document.querySelector('#catalogStatus').value=status;renderCatalog()}else location.hash='curriculum';break;case'zoomIn':graph?.zoom(.74);break;case'zoomOut':graph?.zoom(1.35);break;case'resetCamera':graph?.reset();updateRotateButton(false);break;case'toggleRotate':{const active=graph?.toggleRotate()||false;updateRotateButton(active);break}case'panelToggle':{const hidden=document.querySelector('.map-page').classList.toggle('panel-hidden');el.setAttribute('aria-pressed',String(hidden));el.setAttribute('aria-label',hidden?'Показать карточку':'Скрыть карточку');el.title=hidden?'Показать карточку темы':'Скрыть карточку темы';break;}case'toggleList':listMode=!listMode;renderMapList();break;case'mapHelp':case'showIntroHelp':showHelp();break;case'filterToggle':{const active=document.querySelector('#mapFilter').classList.toggle('open');el.setAttribute('aria-expanded',String(active));break}case'clearSelection':selected=null;pathMode=false;graph?.select(null,false);renderMapPanel();history.replaceState(null,'','#map');break;case'togglePath':pathMode=!pathMode;graph?.select(selected,pathMode);renderMapPanel();history.replaceState(null,'',`#map?id=${selected}${pathMode?'&path=1':''}`);break;case'motionPreference':setMotion(!reduced);toast(reduced?'Движение уменьшено':'Плавные анимации включены');break;case'motionToggle':setMotion(!reduced);el.textContent=`${reduced?'Включить':'Отключить'} анимации`;break;}});
document.addEventListener('input',e=>{if(e.target.id==='catalogSearch'){query=e.target.value;renderCatalog()}if(e.target.id==='mapSearch'){const q=e.target.value.trim().toLowerCase(),el=document.querySelector('#mapResults');const hits=data.nodes.filter(n=>(mapCategory==='all'||n.category===mapCategory)&&`${n.id} ${n.title} ${n.topics.join(' ')}`.toLowerCase().includes(q));el.innerHTML=q?(hits.length?hits.slice(0,8).map(n=>`<button data-select="${n.id}"><small>${n.id}</small>${n.title}</button>`).join(''):'<p style="padding:12px;font-size:11px">Ничего не найдено</p>'):'';renderMapList()}});
document.addEventListener('change',e=>{if(e.target.id==='catalogStatus'){status=e.target.value;renderCatalog()}});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.addEventListener('keydown',e=>{if(currentPage!=='map'||dialog.open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='+'||e.key==='='){e.preventDefault();graph?.zoom(.74)}if(e.key==='-'){e.preventDefault();graph?.zoom(1.35)}if(e.key==='Home'){e.preventDefault();graph?.reset();updateRotateButton(false)}if(e.key==='Escape'){selected=null;pathMode=false;graph?.select(null,false);renderMapPanel();document.querySelector('#mapResults').replaceChildren();history.replaceState(null,'','#map')}});
let routeTransition;
function navigate(){routeTransition?.skipTransition();const update=()=>{render();main.focus({preventScroll:true});};if(document.startViewTransition&&!reduced){routeTransition=document.startViewTransition(update);routeTransition.finished.catch(()=>{});}else update()}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus({preventScroll:false});});
function decorateProgress(){document.querySelectorAll('.progress-bar i').forEach(i=>{const ratio=i.dataset.progress!==undefined?Number(i.dataset.progress):parseFloat(i.style.width)||0;i.style.width='100%';i.style.transform=`scaleX(${ratio/100})`;i.dataset.progress=ratio})}
const headerObserver=new ResizeObserver(entries=>document.documentElement.style.setProperty('--header-height',(entries[0].borderBoxSize?.[0]?.blockSize||document.querySelector('.header').getBoundingClientRect().height)+'px'));headerObserver.observe(document.querySelector('.header'));
window.addEventListener('hashchange',navigate);updateProgress();applyMotion();render();
